import java.lang.reflect.Method;
import java.util.Arrays;

public class Ex09BridgeMethod {
    static class Node<T> {
        T data;
        void setData(T data) { this.data = data; }
    }
    static class IntNode extends Node<Integer> {
        @Override void setData(Integer data) { super.setData(data); }
    }
    public static void main(String[] args) {
        for (Method m : IntNode.class.getDeclaredMethods()) {
            System.out.println("IntNode method: " + m.getName()
                + " paramTypes=" + Arrays.toString(m.getParameterTypes())
                + " bridge=" + m.isBridge());
        }
        Node<Integer> n = new IntNode();
        n.setData(42);
        System.out.println("setData(42) ok, data=" + n.data);
    }
}
